<?php
namespace App\Jobs;
use App\Models\Examination;use App\Models\User;use App\Services\Viva\VivaAuditService;use App\Services\Viva\VivaMappingImportService;use App\Support\Examinations\ExaminationConnectionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;
final class ProcessVivaMappingImport implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=1;public int $timeout=0;public function __construct(public int $examinationId,public int $batchId,public int $actorId){$this->onQueue((string)config('viva.queue','imports'));}public function handle(ExaminationConnectionManager$c,VivaMappingImportService$s,VivaAuditService$a):void{$e=Examination::findOrFail($this->examinationId);$c->configure($e);try{$b=$s->process($this->batchId);$a->record('VIVA_MAPPING_STAGED',User::findOrFail($this->actorId),'queued','staged',summary:['staged_rows'=>(int)$b->staged_rows],batchId:$b->id);}finally{$c->disconnect();}}}
